 window.aetherWikiData.scriptedItemSources=[{"id": 56237, "name": "Twisted bow", "guide": "chambers-of-xeric", "label": "Chambers of Xeric", "detail": "One 1-in-100 party weapon roll; equal selection between Twisted bow and Elder maul. Weighted eligible recipient. Also 10,000,000 Dungeoneering tokens."}, {"id": 56241, "name": "Elder maul", "guide": "chambers-of-xeric", "label": "Chambers of Xeric", "detail": "One 1-in-100 party weapon roll; equal selection between Elder maul and Twisted bow. Weighted eligible recipient. Also 5,000,000 Dungeoneering tokens."}, {"id": 61000, "name": "Obligator", "guide": "fractured-archive", "label": "Fractured Archive", "detail": "One 1-in-100 party equipment roll, then 20% Obligator selection: 1-in-500 party chance. Weighted eligible recipient. Also 12,000,000 Dungeoneering tokens."}, {"id": 61001, "name": "Zorya’s tome", "guide": "fractured-archive", "label": "Fractured Archive", "detail": "One 1-in-100 party equipment roll, then 40% tome selection: 1-in-250 party chance. Weighted eligible recipient. Also 8,000,000 Dungeoneering tokens."}, {"id": 61002, "name": "Rondache", "guide": "fractured-archive", "label": "Fractured Archive", "detail": "One 1-in-100 party equipment roll, then 40% Rondache selection: 1-in-250 party chance. Weighted eligible recipient. Also 5,000,000 Dungeoneering tokens."}, {"id": 61003, "name": "Orion", "guide": "fractured-archive", "label": "Fractured Archive", "detail": "Independent personal 1-in-500 roll per eligible completion, with protection for an owned or pending Orion. Raid-earned only; no token-shop purchase."}, {"id": 61004, "name": "Orion (alternate form)", "guide": "fractured-archive", "label": "Fractured Archive", "detail": "Use Orion’s Metamorphosis option after unlocking the pet. This is a form of the same owned pet, not an additional loot roll or token purchase."}];

 for(const source of window.aetherWikiData.scriptedItemSources)window.aetherWikiData.items[source.id]=source.name;

 for(const pet of [{"key": "i:56235", "name": "Olmlet", "npc": 32305, "cosmetic": false, "signature": "Olmlet's signature", "effect": "This pet's signature has not been configured yet.", "obtain": "Chambers of Xeric: native conditional pet roll after a successful unique reward. Raid-earned only."}, {"key": "i:61003", "name": "Orion", "npc": 32343, "cosmetic": false, "signature": "Orion's signature", "effect": "This pet's signature has not been configured yet.", "obtain": "Fractured Archive: eligible personal 1-in-500 pet roll, with ownership/pending protection; raid-earned only. Metamorphosis shares one pet progression family."}, {"key": "i:56000", "name": "Pet Snakeling", "npc": 32206, "cosmetic": false, "signature": "Pet Snakeling's signature", "effect": "This pet's signature has not been configured yet.", "obtain": "Earned from Zulrah through the server’s Snakeling reward system. It is not a CoX or Dungeoneering shop reward."}])if(!window.aetherWikiData.pets.some(existing=>existing.key===pet.key))window.aetherWikiData.pets.push(pet);


 if(!window.aetherWikiArticles.some(a=>a.id==="zulrah"))window.aetherWikiArticles.push({"id": "zulrah", "title": "Zulrah and toxic equipment", "category": "Boss guides", "custom": true, "summary": "Find Zulrah through the Atlas, earn its rewards and maintain toxic equipment with real supplies. The ammunition and damage changes below are included in the Archive update.", "sections": [{"title": "Enter through the Atlas", "text": "Use the Zulrah destination in the Atlas and prepare food, potions, prayer and ammunition before starting. The server uses its own encounter and earned-kill reward system."}, {"title": "Toxic equipment", "text": "Tanzanite fang can be carved into an empty toxic blowpipe with a chisel at level 78 Fletching. Load the weapon with Zulrah scales and supported darts. It needs both to fire. Use its equipment options to check or refund stored supplies before dropping or trading a charged item."}, {"title": "Ammunition and damage", "text": "The blowpipe accepts the bronze, iron, steel, black, mithril, adamant, rune, dragon and amethyst dart families, including their supported poison variants. Tips and deathtouched darts are not ammunition for this weapon. The main-hand ranged maximum hit increases by 35%; ammunition and scale consumption remain in place."}, {"title": "Pet Snakeling", "text": "Pet Snakeling is earned through the Zulrah reward system. It is not a CoX reward or a Dungeoneering token purchase. Its existing companion entry uses the server ownership and following rules."}, {"title": "Related guides", "links": [["backlog-update", "Equipment update"], ["dungeoneering-rewards", "Dungeoneering rewards"]]}]});
 const starter=window.aetherWikiArticles.find(a=>a.id==="first-steps")?.sections.find(section=>section.title==="Before your first boss");
 if(starter)for(const link of [["chambers-of-xeric","Chambers of Xeric"],["fractured-archive","Fractured Archive"],["zulrah","Zulrah"]])if(!starter.links.some(existing=>existing[0]===link[0]))starter.links.push(link);
 const cleanerGuide=window.aetherWikiArticles.find(article=>article.id==="dungeoneering-rewards");
 if(cleanerGuide&&!cleanerGuide.sections.some(section=>section.title==="Charming imp settings"))cleanerGuide.sections.push({title:"Charming imp settings",text:"Configure the imp to collect, convert to XP or leave each supported family. Use Next page for more choices and the final option to enable or disable the imp. These are base conversion amounts; normal server XP rules apply. Spirit gem variants share the setting for their gem family.",list:["Gold, green, crimson, blue and elder charms: 4, 8, 12, 16 and 20 base Summoning XP each.","Abyssal, talon beast and obsidian charms: 6 base XP each.","Spirit sapphire, emerald, ruby, diamond, dragonstone and onyx: 50, 90, 135, 225, 300 and 500 base XP each.","Full inventory preserves an uncollected drop; blocked XP preserves an item selected for conversion."],external:[["https://runescape.wiki/w/Charming_imp","Charm and spirit gem conversion reference"]]});
